// Full-row update: the handler must Get first and fall back to the stored value
// for every field the request omits.
func (q *Queries) UpdateProcessType(ctx context.Context, arg UpdateProcessTypeParams) (ApplicationProcessType, error) {
	row := q.db.QueryRow(ctx, updateProcessType,
		arg.ID,
		arg.Command,
		arg.Replicas,
		arg.Routable,
		arg.CpuLimit,
		arg.MemoryLimit,
		arg.HealthCheckType,
		arg.HealthCheckCommand,
	)
	var i ApplicationProcessType
	err := row.Scan(
		&i.ID,
		&i.ApplicationID,
		&i.Name,
		&i.Command,
		&i.Replicas,
		&i.Routable,
		&i.CpuLimit,
		&i.MemoryLimit,
		&i.HealthCheckType,
		&i.HealthCheckCommand,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
